#!/usr/bin/env python3
import os
import shutil
import sys
from pathlib import Path


def fail(message: str, code: int = 1) -> int:
    sys.stderr.write(message + "\n")
    return code


def remove_path(path: Path) -> None:
    if path.is_symlink() or path.is_file():
        path.unlink()
    elif path.is_dir():
        shutil.rmtree(path)


def copy_path(src: Path, dst: Path) -> None:
    if src.is_symlink():
        dst.symlink_to(src.readlink())
    elif src.is_dir():
        shutil.copytree(src, dst, symlinks=True)
    else:
        shutil.copy2(src, dst)


def parse_repo_and_args(argv: list[str]) -> tuple[Path, list[str]]:
    repo = Path.cwd()
    work_tree = os.environ.get("GIT_WORK_TREE")
    if work_tree:
        repo = Path(work_tree)
    args = list(argv)
    while args:
        if len(args) >= 2 and args[0] == "-C":
            repo = Path(args[1])
            args = args[2:]
            continue
        if len(args) >= 2 and args[0] == "-c":
            args = args[2:]
            continue
        break
    return repo.resolve(), args


def shim_dir(repo: Path) -> Path:
    return repo / ".git-shim"


def snapshots_dir(repo: Path) -> Path:
    return shim_dir(repo) / "snapshots"


def ensure_repo_dirs(repo: Path) -> None:
    (repo / ".git").mkdir(parents=True, exist_ok=True)
    snapshots_dir(repo).mkdir(parents=True, exist_ok=True)


def snapshot_tree(repo: Path, name: str) -> None:
    ensure_repo_dirs(repo)
    dst = snapshots_dir(repo) / name
    if dst.exists():
        shutil.rmtree(dst)
    dst.mkdir(parents=True, exist_ok=True)
    for child in repo.iterdir():
        if child.name in {".git", ".git-shim"}:
            continue
        copy_path(child, dst / child.name)


def restore_tree(repo: Path, name: str) -> int:
    src = snapshots_dir(repo) / name
    if not src.exists():
        return fail(f"git-shim: unknown snapshot {name!r}")
    for child in repo.iterdir():
        if child.name in {".git", ".git-shim"}:
            continue
        remove_path(child)
    for child in src.iterdir():
        copy_path(child, repo / child.name)
    return 0


def copy_snapshot(repo: Path, src_name: str, dst_name: str) -> None:
    src = snapshots_dir(repo) / src_name
    dst = snapshots_dir(repo) / dst_name
    if dst.exists():
        shutil.rmtree(dst)
    shutil.copytree(src, dst, symlinks=True)


def cmd_init(repo: Path, args: list[str]) -> int:
    target = repo
    positional = [arg for arg in args if not arg.startswith("-")]
    if positional:
        target = Path(positional[-1]).resolve()
    target.mkdir(parents=True, exist_ok=True)
    ensure_repo_dirs(target)
    return 0


def cmd_config(repo: Path, args: list[str]) -> int:
    ensure_repo_dirs(repo)
    return 0


def cmd_add(repo: Path, args: list[str]) -> int:
    ensure_repo_dirs(repo)
    return 0


def cmd_commit(repo: Path, args: list[str]) -> int:
    ensure_repo_dirs(repo)
    root_snapshot = snapshots_dir(repo) / "root"
    if not root_snapshot.exists():
        snapshot_tree(repo, "root")
    snapshot_tree(repo, "head")
    return 0


def cmd_apply(repo: Path, args: list[str]) -> int:
    return fail("git-shim: git apply is unsupported")


def cmd_reset(repo: Path, args: list[str]) -> int:
    target = "head"
    positional = [arg for arg in args if not arg.startswith("-")]
    if positional:
        target = positional[-1].lower()
    if target == "head":
        return restore_tree(repo, "head")
    if target == "root":
        rc = restore_tree(repo, "root")
        if rc == 0:
            copy_snapshot(repo, "root", "head")
        return rc
    return fail(f"git-shim: unsupported reset target {target!r}")


def cmd_clean(repo: Path, args: list[str]) -> int:
    return 0


def cmd_rev_list(repo: Path, args: list[str]) -> int:
    root_snapshot = snapshots_dir(repo) / "root"
    if root_snapshot.exists():
        sys.stdout.write("root\n")
    return 0


def cmd_rev_parse(repo: Path, args: list[str]) -> int:
    normalized = [arg for arg in args if arg != "--verify"]
    if normalized == ["HEAD"] or normalized == ["head"]:
        head_snapshot = snapshots_dir(repo) / "head"
        if not head_snapshot.exists():
            return fail("git-shim: ambiguous argument 'HEAD'")
        sys.stdout.write("head\n")
        return 0
    if normalized == ["--show-toplevel"]:
        sys.stdout.write(str(repo) + "\n")
        return 0
    if normalized == ["--git-dir"]:
        sys.stdout.write(str(repo / ".git") + "\n")
        return 0
    return fail(f"git-shim: unsupported rev-parse arguments {args!r}")


def cmd_log(repo: Path, args: list[str]) -> int:
    sys.stdout.write("commit head\n\n    git-shim synthetic history\n")
    return 0


def cmd_bundle(repo: Path, args: list[str]) -> int:
    if args and args[0] == "create" and len(args) >= 2:
        Path(args[1]).touch()
        return 0
    return fail("git-shim: unsupported bundle invocation")


def main() -> int:
    repo, args = parse_repo_and_args(sys.argv[1:])
    if not args:
        return fail("git-shim: missing command")

    command, command_args = args[0], args[1:]
    if command == "init":
        return cmd_init(repo, command_args)
    if command == "config":
        return cmd_config(repo, command_args)
    if command == "add":
        return cmd_add(repo, command_args)
    if command == "commit":
        return cmd_commit(repo, command_args)
    if command == "apply":
        return cmd_apply(repo, command_args)
    if command == "reset":
        return cmd_reset(repo, command_args)
    if command == "clean":
        return cmd_clean(repo, command_args)
    if command == "rev-list":
        return cmd_rev_list(repo, command_args)
    if command == "rev-parse":
        return cmd_rev_parse(repo, command_args)
    if command == "log":
        return cmd_log(repo, command_args)
    if command == "bundle":
        return cmd_bundle(repo, command_args)
    return fail(f"git-shim: unsupported command {command!r}")


if __name__ == "__main__":
    raise SystemExit(main())

