        return inputs + 1
    def bprop(self, inputs, outputs, grads_wrt_outputs):
        return grads_wrt_outputs

class Scale(LayerWithParameters):
    def __init__(self, s):
        self.w = np.array([[s]], dtype=float)
        self.b = np.array([0.], dtype=float)
    def fprop(self, inputs):
        return inputs * self.w[0,0] + self.b
    def bprop(self, inputs, outputs, grads_wrt_outputs):
        return grads_wrt_outputs * self.w[0,0]
    def grads_wrt_params(self, inputs, grads_wrt_outputs):
        return [np.array([[np.sum(inputs * grads_wrt_outputs)]]), np.array([grads_wrt_outputs.sum()])]
    def params_penalty(self):
        return 0.
    @property
    def params(self):
        return [self.w, self.b]
    @params.setter
    def params(self, values):
        self.w, self.b = values

class MaybeDrop(StochasticLayer):
    def __init__(self):
        super().__init__(None)
        self.called = []
    def fprop(self, inputs, stochastic=True):
        self.called.append(stochastic)
        return inputs if stochastic else inputs * 2
    def bprop(self, inputs, outputs, grads_wrt_outputs):
        return grads_wrt_outputs

single = SingleLayerModel(AddOne())
acts = single.fprop(np.array([[1.]]))
assert len(acts) == 2 and acts[1][0,0] == 2.

