scale = Scale(3.)
model = MultipleLayerModel([stoch, scale, AddOne()])
inputs = np.array([[2.]])
acts = model.fprop(inputs, evaluation=True)
assert stoch.called[-1] is False
assert np.allclose(acts[-1], np.array([[13.]]))
assert len(model.params) == 2
param_grads = model.grads_wrt_params(acts, np.array([[1.]]))
assert len(param_grads) == 2
assert np.allclose(param_grads[0], np.array([[4.]]))
assert np.allclose(param_grads[1], np.array([1.]))
print('models ok')
